def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    N = int(next(iterator))
    M = int(next(iterator))

    edges = []
    adj = [[] for _ in range(N + 1)]

    for _ in range(M):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        edges.append((u, v, w))
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Since N is small (up to 10), we can use DFS to find all simple paths from 1 to N
    # and compute the XOR for each path.

    min_xor = float('inf')

    # DFS to find all simple paths from 1 to N
    # path: list of vertices in the current path
    # current_xor: XOR sum of edge weights in the current path

    def dfs(node, target, visited, current_xor):
        nonlocal min_xor
        if node == target:
            if current_xor < min_xor:
                min_xor = current_xor
            return

        for neighbor, weight in adj[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                dfs(neighbor, target, visited, current_xor ^ weight)
                visited.remove(neighbor)

    visited = {1}
    dfs(1, N, visited, 0)

    print(min_xor)

