class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # Convert each property list to a set for fast intersection counting
        prop_sets = [set(p) for p in properties]

        # Initialize Union-Find
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # Build the graph by checking all pairs
        for i in range(n):
            for j in range(i + 1, n):
                # Count distinct common elements
                common = len(prop_sets[i] & prop_sets[j])
                if common >= k:
                    union(i, j)

        # Count connected components
        roots = set()
        for i in range(n):
            roots.add(find(i))

        return len(roots)
