class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)

        # Helper function to calculate minimum cost to make two characters equal
        def cost(c1, c2):
            diff = abs(ord(c1) - ord(c2))
            return min(diff, 26 - diff)

        # dp[i][j] represents the max palindrome subsequence length we can get
        # from s[i...j] with at most k operations remaining.
        # But since k is limited and we need to track remaining operations,
        # we can use dp[i][j][rem_k] or optimize.
        # Given n <= 200 and k <= 200, O(n^2 * k) might be acceptable.
        # Let's define: dp[i][j][r] = max palindrome length using substring s[i..j] with r operations remaining.

        # To save memory and time, we can use a 3D array or optimize space.
        # Dimensions: n x n x (k+1)
        # Initialize dp with 0

        # We'll use memoization or iterative DP.
        # Let's use iterative DP with base cases.

        # dp[i][j][r] = maximum palindromic subsequence length from s[i..j] with r ops available

        # Base case: single character, always forms palindrome of length 1 with 0 extra ops.
        # dp[i][i][r] = 1 for all r >= 0

        # For substrings of length 2+, we have two choices:
        # 1. Skip s[i]: dp[i+1][j][r]
        # 2. Skip s[j]: dp[i][j-1][r]
        # 3. Match s[i] and s[j]: if cost(s[i], s[j]) <= r, then 2 + dp[i+1][j-1][r - cost(s[i], s[j])]

        # We need to compute for all lengths from 1 to n.

        # Initialize dp[i][j][r] = 0
        # We'll use a 3D list: dp[n][n][k+1]

        dp = [[[0] * (k + 1) for _ in range(n)] for _ in range(n)]

        # Base case: single characters
        for i in range(n):
            for r in range(k + 1):
                dp[i][i][r] = 1

        # Fill for lengths 2 to n
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                for r in range(k + 1):
                    # Option 1: skip s[i]
                    opt1 = dp[i + 1][j][r]
                    # Option 2: skip s[j]
                    opt2 = dp[i][j - 1][r]

                    # Option 3: match s[i] and s[j]
                    c = cost(s[i], s[j])
                    if c <= r:
                        if i + 1 <= j - 1:
                            opt3 = 2 + dp[i + 1][j - 1][r - c]
                        else:
                            # i+1 > j-1 means the inner part is empty, so just 2 characters matched
                            opt3 = 2
                    else:
                        opt3 = 0  # Cannot match

                    dp[i][j][r] = max(opt1, opt2, opt3)

        return dp[0][n - 1][k]
