import sys
from bisect import bisect_left, bisect_right

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    N = int(next(iterator))
    M = int(next(iterator))

    A = []
    for _ in range(N):
        A.append(int(next(iterator)))

    B = []
    for _ in range(M):
        B.append(int(next(iterator)))

    from collections import defaultdict
    pos = defaultdict(list)
    for idx, val in enumerate(A):
        pos[val].append(idx)

    # Compute L: earliest positions for each element of B
    L = [0] * M
    current_idx = -1
    possible = True
    for i in range(M):
        b_val = B[i]
        if b_val not in pos:
            possible = False
            break
        indices = pos[b_val]
        j = bisect_right(indices, current_idx)
        if j == len(indices):
            possible = False
            break
        current_idx = indices[j]
        L[i] = current_idx

    if not possible:
        print("No")
        return

    # Compute R: latest positions for each element of B
    R = [0] * M
    current_idx = N
    for i in range(M-1, -1, -1):
        b_val = B[i]
        indices = pos[b_val]
        j = bisect_left(indices, current_idx)
        if j == 0:
            possible = False
            break
        current_idx = indices[j-1]
        R[i] = current_idx

    if not possible:
        print("No")
        return

    # Check if there are at least two subsequences
    # If L[i] < R[i] for any i, then there are at least two subsequences.
    for i in range(M):
        if L[i] < R[i]:
            print("Yes")
            return

    print("No")

