class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total_k = nums.count(k)
        if n == 0:
            return 0

        # The answer is at least total_k (by doing nothing, i.e., x=0, or any subarray with v=k)
        ans = total_k

        unique_vals = set(nums)

