def solve():
    # Read all input from stdin efficiently
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        # Parse N and M
        if len(input_data) < 2:
            return
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    # Adjacency list for the graph
    # Vertices are 1-indexed, so we use size N + 1
    adj = [[] for _ in range(N + 1)]

    # Parse edges
    for _ in range(M):
        try:
            u = int(next(iterator))
            v = int(next(iterator))
            w = int(next(iterator))
            adj[u].append((v, w))
            adj[v].append((u, w))
        except StopIteration:
            break

    # Iterative DFS to find all simple paths from vertex 1 to vertex N.
    # We maintain the current vertex, the cumulative XOR sum, and a bitmask of visited vertices.
    # Stack stores tuples: (current_vertex, current_xor_sum, visited_mask)
    # Mask bit i corresponds to vertex i+1.
    # Initial state: at vertex 1, xor sum 0, mask has bit 0 set (vertex 1 visited).
    # Binary mask: bit 0 is 1, others 0.
    stack = [(1, 0, 1)]

    min_xor = float('inf')

    while stack:
        u, cx, mask = stack.pop()

        # If we reached the target vertex N
        if u == N:
            if cx < min_xor:
                min_xor = cx
                # 0 is the absolute minimum possible XOR sum since weights are non-negative.
                # If we found a path with XOR sum 0, we can't do better.
                if min_xor == 0:
                    break
            continue

        # Optimization: if min_xor is 0, we can stop searching immediately
        if min_xor == 0:
            break

        # Explore neighbors
        for v, w in adj[u]:
            # Check if v is already visited
            # Vertex v corresponds to bit v-1
            bit = 1 << (v - 1)
            if not (mask & bit):
                # v is not visited, so we can extend the path
                # Push new state to stack
                stack.append((v, cx ^ w, mask | bit))

    print(min_xor)

