import sys

def solve():
    # Read all input from standard input at once.
    # split() handles separating by any whitespace (spaces, newlines).
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        # Read N, the number of dice
        N = int(next(iterator))
    except StopIteration:
        return

    dice = []

    # Parse each die's data
    for _ in range(N):
        try:
            # Read K, the number of faces for the current die
            K = int(next(iterator))

            # Dictionary to store frequency of each face value
            counts = {}
            for _ in range(K):
                val = int(next(iterator))
                if val in counts:
                    counts[val] += 1
                else:
                    counts[val] = 1

            # Store the counts dictionary and total number of faces K
            dice.append((counts, K))
        except StopIteration:
            break

    max_prob = 0.0

    # Iterate over all unique pairs of dice (i, j) with i < j
    # Since N <= 100, O(N^2) is acceptable.
    for i in range(N):
        counts_i, k_i = dice[i]
        len_i = len(counts_i)

        for j in range(i + 1, N):
            counts_j, k_j = dice[j]
            len_j = len(counts_j)

            # Optimization: Iterate over the dictionary with fewer unique values
            # to minimize lookups in the other dictionary.
            if len_i < len_j:
                smaller, larger = counts_i, counts_j
            else:
                smaller, larger = counts_j, counts_i

            overlap_sum = 0
            # Compute the sum of products of counts for common face values.
            # This is equivalent to sum(C_i(x) * C_j(x)) over all x.
            for val, count_small in smaller.items():
                if val in larger:
                    overlap_sum += count_small * larger[val]

            # The probability that both dice show the same number is
            # (sum of products of counts) / (product of total faces).
            # P(match) = sum( (C_i(x)/K_i) * (C_j(x)/K_j) )
            #          = (1 / (K_i * K_j)) * sum(C_i(x) * C_j(x))
            prob = overlap_sum / (k_i * k_j)

            if prob > max_prob:
                max_prob = prob

    # Print the maximum probability with sufficient precision.
    # 15 decimal places ensures error < 10^-8.
    print(f"{max_prob:.15f}")

if __name__ == '__main__':
    solve()
