from collections import deque
from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Build reversed adjacency list: edge u -> v becomes v -> u
        # We reverse because we need 0 to be reachable from all nodes,
        # which is equivalent to 0 reaching all nodes in the reversed graph.
        rev_adj = [[] for _ in range(n)]
        weights = set()
        for u, v, w in edges:
            rev_adj[v].append((u, w))
            weights.add(w)

        if not weights:
            return -1

        sorted_weights = sorted(weights)

        # Check if it's possible to satisfy all conditions with max weight <= max_w
        def check(max_w):
            visited = [False] * n
            out_degree = [0] * n
            visited[0] = True
            q = deque([0])
            count = 1

            while q:
                u = q.popleft()
                # If u has already used up its outgoing edge quota, we can't add more edges from it
                if out_degree[u] >= threshold:
                    continue

                for v, w in rev_adj[u]:
                    if w > max_w:
                        continue
                    if visited[v]:
                        continue

                    # Greedily assign this edge
                    visited[v] = True
                    out_degree[u] += 1
                    q.append(v)
                    count += 1
                    if count == n:
                        return True
            return count == n

        # If even the maximum weight edge doesn't work, it's impossible
        if not check(sorted_weights[-1]):
            return -1

        # Binary search for the minimum feasible maximum weight
        low, high = 0, len(sorted_weights) - 1
        ans = sorted_weights[-1]

        while low <= high:
            mid = (low + high) // 2
            if check(sorted_weights[mid]):
                ans = sorted_weights[mid]
                high = mid - 1
            else:
                low = mid + 1

        return ans
