class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        # offline_until[i] stores the timestamp when user i comes back online.
        # Initially 0, implying users are online for any timestamp >= 1.
        offline_until = [0] * numberOfUsers

        for event in events:
            etype = event[0]
            timestamp = int(event[1])
            payload = event[2]

            if etype == "OFFLINE":
                # Payload is the user ID string (e.g., "0", "1")
                user_id = int(payload)
                # User goes offline at timestamp, and comes back online at timestamp + 60.
                # We record the time they become available again.
                offline_until[user_id] = timestamp + 60

            elif etype == "MESSAGE":
                if payload == "ALL":
                    # "ALL" mentions every user, regardless of online status.
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif payload == "HERE":
                    # "HERE" mentions only currently online users.
                    for i in range(numberOfUsers):
                        # User is online if current time is >= time they became online.
                        # If offline_until[i] is 0 (initial), 0 <= timestamp is true.
                        if timestamp >= offline_until[i]:
                            mentions[i] += 1
                else:
                    # Payload contains space-separated "id<number>" tokens.
                    # Example: "id1 id0"
                    tokens = payload.split()
                    for token in tokens:
                        # Token format is "id<number>"
                        if token.startswith("id"):
                            try:
                                # Extract the number part after "id"
                                id_str = token[2:]
                                if id_str:
                                    user_id = int(id_str)
                                    # Mentioning a specific ID works even if user is offline.
                                    mentions[user_id] += 1
                            except ValueError:
                                # In case of malformed token, ignore it.
                                pass

        return mentions
